const imageBitmapCache=new Map;onmessage=async a=>{let e=a.data.imageURL;try{if(imageBitmapCache.has(e)){let t=imageBitmapCache.get(e);postMessage({imageURL:e,imageBitmap:t});return}let i=await caches.match(e);if(i){let m=await i.blob(),r=await createImageBitmap(m,{imageOrientation:"flipY"});imageBitmapCache.set(e,r),postMessage({imageURL:e,imageBitmap:r});return}let g=await fetch(e);if(!g.ok)throw Error(`Failed to fetch image: ${g.status} ${g.statusText}`);let o=await caches.open("panorama-tiles-cache");await o.put(e,g.clone());let c=await g.blob(),l=await createImageBitmap(c,{imageOrientation:"flipY"});imageBitmapCache.set(e,l),postMessage({imageURL:e,imageBitmap:l})}catch(n){console.error("Error in worker:",n),postMessage({imageURL:e,error:n.message})}};